WITH pin AS MATERIALIZED(SELECT * FROM jsonb_to_recordset($pins$__SOURCE_PIN_JSON__$pins$::jsonb) AS x(day bigint,date date,id text,sha text,n int,verified int)),
calendarpin AS MATERIALIZED(SELECT * FROM jsonb_to_recordset($calendarpins$__CALENDAR_PIN_JSON__$calendarpins$::jsonb) AS x(date date,scope text,source_calendar_manifest_sha256 text,record_sha256 text,receipt_sha256 text,qualification text)),
anchors AS MATERIALIZED(SELECT * FROM population_top3000_202608_202609_v1.working_accepted_companies_v1),
ap AS MATERIALIZED(SELECT p.*,count(*)OVER(PARTITION BY company_id) n FROM population_top3000_202608_202609_v1.ref01_practical_instrument_point_v3 p
WHERE p.cohort_sha256='2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec' AND p.eligible AND p.point_date='2026-08-03'),
days AS MATERIALIZED(SELECT s.*,d.content_text::jsonb body,(s.source_sha256=d.source_sha256 AND d.source_sha256=encode(sha256(convert_to(d.content_text,'UTF8')),'hex') AND d.content_bytes=octet_length(d.content_text)
AND d.source_uri='https://api.massive.com/v2/aggs/grouped/locale/us/market/stocks/'||s.session_date::text||'?adjusted=false&include_otc=false' AND s.source_id=x.id AND s.source_sha256=x.sha AND s.result_count=x.n AND s.verified_source_records=x.verified AND d.source_provider='Massive'
AND jsonb_typeof(d.content_text::jsonb->'results')='array' AND jsonb_array_length(d.content_text::jsonb->'results')=x.n)IS TRUE body_ok
FROM pin x JOIN population_top3000_202608_202609_v1.d02_daily_source_v2 s ON s.source_day_id=x.day AND s.session_date=x.date JOIN population_top3000_202608_202609_v1.source_document d ON d.source_id=s.source_id),
calendarchecks AS MATERIALIZED(SELECT population_top3000_202608_202609_v1.ctx06_aug03_check_v5((count(*)=1 AND bool_and(c.source_record_sha256=cp.record_sha256 AND c.source_receipt_sha256=cp.receipt_sha256 AND c.qualification=cp.qualification AND c.source_record_sha256=encode(sha256(convert_to(c.source_record_text,'UTF8')),'hex') AND c.source_receipt_sha256=encode(sha256(convert_to(c.source_receipt_text,'UTF8')),'hex') AND ds.calendar_scope_id=cp.scope AND ds.calendar_manifest_sha256=cp.source_calendar_manifest_sha256))IS TRUE,'D02_EXACT_CALENDAR_PINS')ok FROM calendarpin cp JOIN population_top3000_202608_202609_v1.catalog_calendar c ON c.session_date=cp.date AND c.scope_id=cp.scope JOIN days ds ON ds.session_date=cp.date),
sourcechecks AS MATERIALIZED(SELECT population_top3000_202608_202609_v1.ctx06_aug03_check_v5((count(*)=1 AND count(DISTINCT session_date)=1 AND bool_and(body_ok IS TRUE) AND sum(result_count)=(SELECT sum(n) FROM pin))IS TRUE,'D02_EXACT_ONE_SOURCE_HEADER_PINS')ok FROM days),
anchorchecks AS MATERIALIZED(SELECT population_top3000_202608_202609_v1.ctx06_aug03_check_v5((count(*)=3000 AND count(DISTINCT company_id)=3000 AND count(DISTINCT selection_order)=3000 AND min(selection_order)=1 AND max(selection_order)=3000 AND bool_and(membership_accepted AND cohort_sha256='2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec' AND membership_acceptance_sha256='20b9dac759857e9b510ccaeca33e4a94d8c748d588fb0cc27740cc66c389b5f9'))IS TRUE,'D02_EXACT_3000_ACCEPTED_ANCHORS')ok FROM anchors),
raw_daily AS MATERIALIZED(SELECT ds.source_day_id,x.rec,x.ord::int source_row,x.rec->>'T' ticker,count(*)OVER(PARTITION BY ds.source_day_id,x.rec->>'T') n FROM days ds CROSS JOIN LATERAL jsonb_array_elements(ds.body->'results')WITH ORDINALITY x(rec,ord) WHERE x.rec->>'T' IN(SELECT anchor_ticker FROM anchors)),
raw_counts AS MATERIALIZED(SELECT source_day_id,ticker,max(n)::integer actual_source_rows FROM raw_daily GROUP BY source_day_id,ticker),
points AS MATERIALIZED(SELECT p.*,count(*)OVER(PARTITION BY company_id,point_date) n FROM population_top3000_202608_202609_v1.ref01_practical_dated_instrument_v3 p
WHERE p.cohort_sha256='2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec' AND p.point_date IN(SELECT session_date FROM days)),
refdocs AS MATERIALIZED(SELECT d.source_id,d.source_sha256,d.evidence->>'as_of' reference_date,d.content_text::jsonb body,
(d.source_sha256=encode(sha256(convert_to(d.content_text,'UTF8')),'hex') AND d.content_bytes=octet_length(d.content_text) AND d.source_provider='Massive')IS TRUE body_ok
FROM population_top3000_202608_202609_v1.source_document d WHERE d.source_id IN(SELECT p.content->>'source_id' FROM points p)),
refraw AS MATERIALIZED(SELECT rd.source_id,rd.source_sha256,rd.reference_date,rd.body_ok,x.ord::integer ordinal,x.rec rawref FROM refdocs rd CROSS JOIN LATERAL jsonb_array_elements(rd.body->'results')WITH ORDINALITY x(rec,ord) WHERE x.rec->>'ticker' IN(SELECT anchor_ticker FROM anchors)),
legacy_docs AS MATERIALIZED(SELECT r.job_id,r.sha256,r.raw_text::jsonb body,(r.sha256=encode(sha256(convert_to(r.raw_text,'UTF8')),'hex')AND r.source_bytes=octet_length(r.raw_text))IS TRUE body_ok FROM(SELECT DISTINCT source_job_id FROM ap WHERE n=1 AND EXISTS(SELECT 1 FROM days WHERE session_date=DATE '2026-08-03'))x JOIN population_top3000_202608_202609_v1.acquisition_raw r ON r.job_id=x.source_job_id),
legacy_raw AS MATERIALIZED(SELECT d.job_id,d.sha256,d.body_ok,x.rec,x.ord::integer ordinal FROM legacy_docs d CROSS JOIN LATERAL jsonb_array_elements(d.body->'results')WITH ORDINALITY x(rec,ord)WHERE x.rec->>'ticker' IN(SELECT anchor_ticker FROM anchors)),
joined AS MATERIALIZED(SELECT a.selection_order,a.company_id,a.anchor_ticker,a.anchor_composite_figi,a.anchor_share_class_figi,a.anchor_security_type,a.anchor_exchange,ds.session_date,ds.source_day_id,ds.body_ok daily_body_ok,
p.n pn,p.content pc,p.record_sha256 pointsha,p.source_set_sha256,p.ticker pticker,ap.n an,ap.content ac,ap.record_sha256 anchorsha,
r.content rc,r.record_sha256 refsha,r.ordinal refordinal,rd.body_ok refbody_ok,rd.source_sha256 refbodysha,rd.reference_date,rd.rawref,ap.source_job_id legacy_job,lad.body_ok legacy_body_ok,lad.sha256 legacy_bodysha,lad.rec legacy_rec,lad.ordinal legacy_ord,
rcnt.actual_source_rows,raw.n rn,raw.rec dailyrec,raw.source_row,b.source_ticker,b.provider_time_ms,b.provider_ny_date,b.provider_close,b.share_volume,b.provider_vwap,b.missing_mask,b.invalid_mask,b.structure_mask,b.raw_record_sha256
FROM anchors a CROSS JOIN days ds CROSS JOIN sourcechecks sc CROSS JOIN anchorchecks ach CROSS JOIN calendarchecks cc
LEFT JOIN ap ON ap.company_id=a.company_id AND ap.n=1 LEFT JOIN points p ON p.company_id=a.company_id AND p.point_date=ds.session_date AND p.n=1
LEFT JOIN population_top3000_202608_202609_v1.ref01_date_record_v4 r ON r.source_id=p.content->>'source_id' AND r.ordinal=(p.content->>'source_ordinal')::integer
LEFT JOIN refraw rd ON rd.source_id=r.source_id AND rd.ordinal=r.ordinal LEFT JOIN legacy_raw lad ON lad.job_id=ap.source_job_id AND lad.ordinal=ap.source_ordinal
LEFT JOIN raw_counts rcnt ON rcnt.source_day_id=ds.source_day_id AND rcnt.ticker=a.anchor_ticker LEFT JOIN raw_daily raw ON raw.source_day_id=ds.source_day_id AND raw.ticker=a.anchor_ticker AND raw.n=1
LEFT JOIN population_top3000_202608_202609_v1.d02_daily_bar_v2 b ON b.source_day_id=raw.source_day_id AND b.source_row=raw.source_row WHERE sc.ok AND ach.ok AND cc.ok),
classified AS MATERIALIZED(SELECT j.*,CASE
WHEN pn IS DISTINCT FROM 1 THEN 'MISSING_OR_AMBIGUOUS_DATED_POINT'
WHEN ((session_date=DATE '2026-08-03' AND an=1 AND anchorsha=encode(sha256(convert_to(ac::text,'UTF8')),'hex') AND pointsha=encode(sha256(convert_to(pc::text,'UTF8')),'hex') AND legacy_body_ok AND source_set_sha256='27c81878e9ea5ce6eb05ead025f5c9aaae11108af50ba59ecd65b3402c877c86' AND pc->>'identity_basis'='REVIEWED_FROZEN_IDENTITY_POINT' AND pc->>'point_record_sha256'=anchorsha AND pc->>'source_job_id'=legacy_job AND(pc->>'source_ordinal')::integer=legacy_ord AND pc->>'source_sha256'=legacy_bodysha AND ac->>'source_sha256'=legacy_bodysha AND pc->>'source_record_sha256'=encode(sha256(convert_to(legacy_rec::text,'UTF8')),'hex') AND ac->'source_record'=legacy_rec AND pc->>'company_id'=company_id AND pc->>'point_date'=session_date::text AND pticker=anchor_ticker AND legacy_rec->>'ticker'=anchor_ticker AND nullif(legacy_rec->>'composite_figi','')=anchor_composite_figi AND nullif(legacy_rec->>'share_class_figi','')=anchor_share_class_figi AND nullif(legacy_rec->>'cik','')IS NOT NULL AND nullif(ac#>>'{source_record,cik}','')IS NOT NULL AND legacy_rec->>'cik'=ac#>>'{source_record,cik}' AND legacy_rec->>'type'=anchor_security_type AND legacy_rec->>'primary_exchange'=anchor_exchange AND legacy_rec->>'active'='true' AND legacy_rec->>'market'='stocks' AND legacy_rec->>'locale'='us') OR (session_date<>DATE '2026-08-03' AND (an=1 AND anchorsha=encode(sha256(convert_to(ac::text,'UTF8')),'hex') AND pointsha=encode(sha256(convert_to(pc::text,'UTF8')),'hex')
AND refsha=encode(sha256(convert_to(rc::text,'UTF8')),'hex') AND refsha=pc->>'source_record_sha256' AND refbody_ok AND source_set_sha256=refbodysha
AND reference_date=session_date::text AND rc->>'point_date'=session_date::text AND rc->>'company_id'=company_id AND rc->'source_record'=rawref AND pc->>'anchor_record_sha256'=anchorsha AND pc->>'company_id'=company_id AND pc->>'point_date'=session_date::text
AND pticker=anchor_ticker AND rawref->>'ticker'=anchor_ticker AND nullif(rawref->>'composite_figi','')=anchor_composite_figi AND nullif(rawref->>'share_class_figi','')=anchor_share_class_figi
AND nullif(rawref->>'cik','') IS NOT NULL AND nullif(ac#>>'{source_record,cik}','') IS NOT NULL AND rawref->>'cik'=ac#>>'{source_record,cik}' AND rawref->>'type'=anchor_security_type AND rawref->>'primary_exchange'=anchor_exchange
AND rawref->>'active'='true' AND rawref->>'market'='stocks' AND rawref->>'locale'='us'))) IS DISTINCT FROM TRUE THEN 'POINT_RAW_ANCHOR_MISMATCH'
WHEN rn IS DISTINCT FROM 1 THEN 'MISSING_OR_DUPLICATE_SOURCE_TICKER'
WHEN (daily_body_ok AND source_ticker=anchor_ticker AND provider_ny_date=session_date AND missing_mask=0 AND invalid_mask=0 AND structure_mask=0
AND provider_time_ms=(dailyrec->>'t')::numeric AND raw_record_sha256=sha256(convert_to(dailyrec::text,'UTF8')) AND provider_close=(dailyrec->>'c')::numeric AND share_volume=(dailyrec->>'v')::numeric
AND provider_vwap IS NOT DISTINCT FROM(dailyrec->>'vw')::numeric AND provider_close>0 AND share_volume>=0)IS DISTINCT FROM TRUE THEN 'SOURCE_VALUE_OR_RAW_LINK_MISMATCH'
ELSE 'VERIFIED_POINT_AND_SOURCE_LINK' END state FROM joined j)